package com.PixBrew.vocabMitra.entity;

import com.PixBrew.vocabMitra.type.OrderPaymentStatus;
import jakarta.persistence.*;
import lombok.*;
import org.hibernate.annotations.CreationTimestamp;
import org.hibernate.annotations.UpdateTimestamp;

import java.time.Instant;
import java.time.LocalDateTime;

@Entity
@Table(name = "subscription_order")
@AllArgsConstructor
@NoArgsConstructor
@Builder
@Getter
@Setter
public class SubscriptionOrder {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private long orderId;

    // Generated by Razorpay when the user clicks "Buy"
    @Column(nullable = false, unique = true)
    private String razorpayOrderId;

    // Received from Razorpay after a successful payment
    @Column(unique = true)
    private String razorpayPaymentId;

    // The digital signature to prove the payment is authentic
    private String razorpaySignature;

    // e.g., "CREATED", "SUCCESS", "FAILED"
    @Column(nullable = false)
    @Enumerated(EnumType.STRING)
    private OrderPaymentStatus status;

    // The number of months they purchased (1, 2, or 3)
    private int durationMonths;

    // Amount stored in subunits (Paise) as per Razorpay standards
    private int amountPaid;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id", nullable = false)
    private Users user;

    @CreationTimestamp
    @Column(updatable = false)
    private Instant createdAt;

    @UpdateTimestamp
    private Instant updatedAt;
}
